@pytest.mark.parametrize("seconds",[None,.125,2.5])
def test_request_records(seconds):
    explicit={"connect":seconds,"read":seconds,"write":seconds,"pool":seconds}
    extensions={"timeout":explicit,"trace-tag":"retained"}
    seen=[]
    def handle(request):
        seen.append(dict(request.extensions))
        return httpx.Response(200)
    with httpx.Client(transport=httpx.MockTransport(handle),timeout=9,trust_env=False) as client:
        request=client.build_request("GET","https://example.test/route",timeout=.75,extensions=extensions)
        client.send(request)
    assert seen[0]["timeout"] == explicit
    assert seen[0]["trace-tag"] == "retained"
    assert extensions == {"timeout":explicit,"trace-tag":"retained"}

def _send_handling_auth(
    self,
    request: Request,
    auth: Auth,
    follow_redirects: bool,
    history: list[Response],
) -> Response:
    auth_flow = auth.sync_auth_flow(request)
    try:
        request = next(auth_flow)

        while True:
            response = self._send_handling_redirects(
                request,
                follow_redirects=follow_redirects,
                history=history,
            )
            try:
                try:
                    next_request = auth_flow.send(response)
                except StopIteration:
                    return response

                response.history = list(history)
                response.read()
                request = next_request
                history.append(response)

            except BaseException as exc:
                response.close()
                raise exc
    finally:
        auth_flow.close()

def _set_timeout(self, request: Request) -> None:
    if "timeout" not in request.extensions:
        timeout = (
            self.timeout
            if isinstance(self.timeout, UseClientDefault)
            else Timeout(self.timeout)
        )
        request.extensions = dict(**request.extensions, timeout=timeout.as_dict())

def _send_handling_redirects(
    self,
    request: Request,
    follow_redirects: bool,
    history: list[Response],
) -> Response:
    while True:
        if len(history) > self.max_redirects:
            raise TooManyRedirects(
                "Exceeded maximum allowed redirects.", request=request
            )

        for hook in self._event_hooks["request"]:
            hook(request)

        response = self._send_single_request(request)
        try:
            for hook in self._event_hooks["response"]:
                hook(response)
            response.history = list(history)

            if not response.has_redirect_location:
                return response

            request = self._build_redirect_request(request, response)
            history = history + [response]

            if follow_redirects:
                response.read()
            else:
                response.next_request = request
                return response

        except BaseException as exc:
            response.close()
            raise exc

def sync_auth_flow(
    self, request: Request
) -> typing.Generator[Request, Response, None]:
    """
    Execute the authentication flow synchronously.

    By default, this defers to `.auth_flow()`. You should override this method
    when the authentication scheme does I/O and/or uses concurrency primitives.
    """
    if self.requires_request_body:
        request.read()

    flow = self.auth_flow(request)
    request = next(flow)

    while True:
        response = yield request
        if self.requires_response_body:
            response.read()

        try:
            request = flow.send(response)
        except StopIteration:
            break

def iter_bytes(self, chunk_size: int | None = None) -> typing.Iterator[bytes]:
    """
    A byte-iterator over the decoded response content.
    This allows us to handle gzip, deflate, brotli, and zstd encoded responses.
    """
    if hasattr(self, "_content"):
        chunk_size = len(self._content) if chunk_size is None else chunk_size
        for i in range(0, len(self._content), max(chunk_size, 1)):
            yield self._content[i : i + chunk_size]
    else:
        decoder = self._get_content_decoder()
        chunker = ByteChunker(chunk_size=chunk_size)
        with request_context(request=self._request):
            for raw_bytes in self.iter_raw():
                decoded = decoder.decode(raw_bytes)
                for chunk in chunker.decode(decoded):
                    yield chunk
            decoded = decoder.flush()
            for chunk in chunker.decode(decoded):
                yield chunk  # pragma: no cover
            for chunk in chunker.flush():
                yield chunk

def as_dict(self) -> dict[str, float | None]:
    return {
        "connect": self.connect,
        "read": self.read,
        "write": self.write,
        "pool": self.pool,
    }

def _merge_queryparams(
    self, params: QueryParamTypes | None = None
) -> QueryParamTypes | None:
    """
    Merge a queryparams argument together with any queryparams on the client,
    to create the queryparams used for the outgoing request.
    """
    if params or self.params:
        merged_queryparams = QueryParams(self.params)
        return merged_queryparams.merge(params)
    return params

