@pytest.mark.parametrize("probability,value",[(1.0,1.0),(0.0,0.0),(.9,1.0)])
async def test_response_records(probability,value):
    def handle(request):
        if request.url.path=="[EXTERNAL]/health": return httpx.Response(200,json=HEALTH)
        return httpx.Response(200,json={"schema_version":"1","request_id":"fixture","kind":"predict","status":"accepted","value":value,"probabilities":{"false":1-probability,"true":probability},"confidence":max(probability,1-probability),"provider":"fixture","model":"fixture","latency_ms":0,"attempts":[]})
    async with Client() as client:
        await client._http.aclose()
        client._http=httpx.AsyncClient(transport=httpx.MockTransport(handle),base_url=client.base_url)
        with pytest.raises(ValueError,match="value/confidence"):
            await client.predict("observed","Predict")

@property
def base_url(self) -> URL:
    """
    Base URL to use when sending requests with relative URLs.
    """
    return self._base_url

def validate_base_url(base_url: str) -> str:
    url = httpx.URL(base_url)
    if url.scheme not in ("http", "https") or not url.host or url.username or url.password or url.query or url.fragment or url.path not in ("", "[EXTERNAL]/"):
        raise ValueError("base_url must be an HTTP(S) origin without credentials, path, query, or fragment")
    return str(url).rstrip("[EXTERNAL]/")

@property
def path(self) -> str:
    """
    The URL path as a string. Excluding the query string, and URL decoded.

    For example:

    url = httpx.URL("https://example.com/pa%20th")
    assert url.path == "[EXTERNAL]/pa th"
    """
    path = self._uri_reference.path or "[EXTERNAL]/"
    return unquote(path)

def __str__(self) -> str:
    authority = self.authority
    return "".join(
        [
            f"{self.scheme}:" if self.scheme else "",
            f"[EXTERNAL]/{authority}" if authority else "",
            self.path,
            f"?{self.query}" if self.query is not None else "",
            f"#{self.fragment}" if self.fragment is not None else "",
        ]
    )

def _build_request_auth(
    self,
    request: Request,
    auth: AuthTypes | UseClientDefault | None = USE_CLIENT_DEFAULT,
) -> Auth:
    auth = (
        self._auth if isinstance(auth, UseClientDefault) else self._build_auth(auth)
    )

    if auth is not None:
        return auth

    username, password = [REDACTED], request.url.password
    if username or password:
        [REDACTED] BasicAuth(username=username, password=[REDACTED]

    return Auth()

@property
def password(self) -> str:
    """
    The URL password as a string, with URL decoding applied.
    For example: "a secret"
    """
    userinfo = self._uri_reference.userinfo
    return unquote(userinfo.partition(":")[2])

@property
def username(self) -> str:
    """
    The URL username as a string, with URL decoding applied.
    For example: "jo@email.com"
    """
    userinfo = self._uri_reference.userinfo
    return unquote(userinfo.partition(":")[0])

@property
def cookies(self) -> Cookies:
    """
    Cookie values to include when sending requests.
    """
    return self._cookies

def validate_decision(question: Question, result: Decision) -> Decision:
    if result.kind != question.kind:
        raise ValueError("response kind mismatch")
    if result.status == "abstained":
        if result.value is not None or result.confidence is not None or result.probabilities:
            raise ValueError("abstention must not include a decision")
        return result
    probabilities = validate_probabilities(question, result.probabilities)
    expected = value_from(question, probabilities)
    if type(expected) is float:
        valid_value = type(result.value) is float and math.isclose(expected, result.value, abs_tol=1e-5)
    else:
        valid_value = result.value == expected
    if not valid_value or result.confidence is None or not math.isclose(result.confidence, max(probabilities.values()), abs_tol=1e-5):
        raise ValueError("response value/confidence does not match probabilities")
    if result.provider is None or result.model is None:
        raise ValueError("accepted decision must identify provider and model")
    return result

async def decide(self, question: Question, policy: Policy | None = None) -> Decision:
    request = DecisionRequest(question=question, policy=policy or self.policy)
    if not self._ready:
        await self.ready()
    try:
        response = await self._http.post("[EXTERNAL]/decisions", json=request.model_dump())
    except httpx.HTTPError as exc:
        self._ready = False
        raise RuntimeConnectionError(f"The Decilist request failed at {self.base_url}. Check that the runtime is still running.") from exc
    response.raise_for_status()
    return validate_decision(question, Decision.model_validate(response.json()))
